// Bundles a repo's README, manifest, and a handful of representative source
// files into one clean text blob, ready to paste directly into any AI chat
// tool ("ChatGPT, explain this codebase") without cloning it locally first.
// Reuses the exact same file-selection logic as core/explain.js (see
// core/sourceSampler.js) but asks for more files and bigger excerpts, since
// there's no per-request AI cost to bound here - the bundle is just handed
// back to the caller, never sent to an LLM by this server.
import { getRepoOverview } from './inspect.js';
import { sampleRepoFiles } from './sourceSampler.js';
import { truncate } from '../lib/format.js';

const MAX_CODE_FILES = 6;
const CODE_EXCERPT_CHARS = 6000;
const README_CHARS = 10000;

function formatFileSection(path, text, truncated) {
    const ext = path.includes('.') ? path.split('.').pop() : '';
    return [
        `### ${path}${truncated ? ' (truncated)' : ''}`,
        '```' + ext,
        text,
        '```',
    ].join('\n');
}

export async function bundleRepoContext({ repo, githubToken }) {
    const [{ info, readme, languages, contributorCount, release }, codeFiles] = await Promise.all([
        getRepoOverview({ repo, token: githubToken }),
        sampleRepoFiles(repo, githubToken, { maxCodeFiles: MAX_CODE_FILES, excerptChars: CODE_EXCERPT_CHARS }),
    ]);

    const topLanguages = languages
        ? Object.entries(languages).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([l]) => l).join(', ')
        : 'unknown';
    const license = info.license?.spdx_id && info.license.spdx_id !== 'NOASSERTION' ? info.license.spdx_id : info.license?.name;
    const { text: readmeExcerpt, truncated: readmeTruncated } = truncate((readme || '').trim(), README_CHARS);

    const sections = [
        `# ${info.full_name} — context bundle`,
        '',
        `Generated by Gitty (${info.html_url}) for pasting into an AI chat. This is a partial snapshot - ` +
        `a README excerpt, the dependency manifest, and a handful of representative source files - not the full repository.`,
        '',
        '## Repo info',
        `- Description: ${info.description || '(none provided)'}`,
        `- URL: ${info.html_url}`,
        `- Primary languages: ${topLanguages}`,
        `- Stars: ${info.stargazers_count} | Forks: ${info.forks_count} | Open issues: ${info.open_issues_count}`,
        `- License: ${license || 'none declared'}`,
        `- Archived: ${info.archived ? 'yes' : 'no'}`,
        `- Contributors: ${contributorCount != null ? `~${contributorCount}` : 'unknown'}`,
        `- Latest release: ${release ? release.tag_name : 'none published'}`,
        '',
        '## README' + (readmeTruncated ? ' (truncated)' : ''),
        readmeExcerpt || '(No README available.)',
    ];

    if (codeFiles.length) {
        sections.push('', '## Sampled source files');
        for (const { path, text, truncated } of codeFiles) {
            sections.push('', formatFileSection(path, text, truncated));
        }
    }

    return { repo: info.full_name, fileCount: codeFiles.length, bundle: sections.join('\n') };
}
